MaxUptime.query:
SELECT '' AS error \
        FROM uptime \
        WHERE total_seconds / 60 / 60 / 24 > 30;

SystemIntegrityProtection.query:
SELECT 'SIP flag ' || CAST(config_flag AS TEXT) || ' is enabled' AS error \
        FROM sip_config \
        WHERE config_flag == 1;

Firewall.query:
SELECT '' AS error \
        FROM alf \
        WHERE global_state == 0;

GatekeeperEnabled.query:
SELECT '' AS error \
        FROM gatekeeper \
        WHERE assessments_enabled != 1;

SSHKeys.query:
SELECT path AS error \
        FROM user_ssh_keys \
        WHERE encrypted = 0;
